import pytest

BITS: int = 8
MASK: int = 0xFF


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits to the low end.

    x is in 0..255 and k is in 0..7. The result is in 0..255.
    """
    x &= MASK
    k %= BITS
    return ((x << k) | (x >> (BITS - k))) & MASK


def test_rotl8_no_rotation() -> None:
    assert rotl8(0xAB, 0) == 0xAB
    assert rotl8(0, 0) == 0


def test_rotl8_single_bit_wraps() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_top_bits_wrap() -> None:
    assert rotl8(0b11000000, 2) == 0b00000011


def test_rotl8_all_ones_fixed() -> None:
    assert rotl8(0xFF, 3) == 0xFF
    assert rotl8(0xFF, 7) == 0xFF


def test_rotl8_single_bit_to_top() -> None:
    assert rotl8(0x01, 7) == 0x80


@pytest.mark.parametrize("k", range(8))
def test_rotl8_result_in_range(k: int) -> None:
    for x in range(256):
        r = rotl8(x, k)
        assert 0 <= r <= MASK
